//! Btrfs filesystem **in** the blob artifact.
//!
//! The outermost deployment artifact is a btrfs filesystem image whose
//! contents are the sealed plugin object blobs plus an index — the "blob is
//! complete" deployment unit from BLOB_ARCHITECTURE_SYNTHESIS.md: mountable
//! (loop/ro), snapshottable, `btrfs send/receive`-able, and self-describing.
//!
//! Layout inside the image:
//!
//! ```text
//! /blobs/<plugin_id>/<plugin_id>.<hash16>.blob   (one subvolume per plugin
//! /blob-index.json                                when btrfs-progs supports
//!                                                 --subvol; plain dirs otherwise)
//! ```
//!
//! Sealing uses `mkfs.btrfs --rootdir --shrink`, which populates the image
//! from a staging directory **without mounting** — no root privileges needed.
//! Runtime consumption of blobs stays on tmpfs (REQ-8.3); the btrfs image is
//! the at-rest/transport form, activated by loop-mounting read-only and
//! loading the catalog from the mountpoint.

use crate::blob::BlobRef;
use std::io;
use std::path::{Path, PathBuf};
use std::process::Command;

/// Btrfs superblock magic "_BHRfS_M" at superblock offset 0x10000 + 0x40.
const BTRFS_MAGIC_OFFSET: u64 = 0x10040;
const BTRFS_MAGIC: &[u8; 8] = b"_BHRfS_M";

#[derive(Debug)]
pub struct BtrfsImageReport {
    pub image_path: PathBuf,
    pub image_bytes: u64,
    pub blob_count: usize,
    pub subvolumes: bool,
    pub mount_hint: String,
}

/// Seal a set of sealed `.blob` files into a btrfs filesystem image.
pub fn seal_blobs_into_btrfs_image(
    blob_paths: &[PathBuf],
    image_path: &Path,
) -> io::Result<BtrfsImageReport> {
    if blob_paths.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "no blobs to seal",
        ));
    }
    if which_mkfs().is_none() {
        return Err(io::Error::new(
            io::ErrorKind::NotFound,
            "mkfs.btrfs not found (install btrfs-progs)",
        ));
    }

    // Stage: /blobs/<plugin_id>/<file>, /blob-index.json
    let staging = staging_dir(image_path)?;
    let blobs_root = staging.join("blobs");
    std::fs::create_dir_all(&blobs_root)?;

    let mut index = Vec::new();
    let mut total: u64 = 0;
    let mut subvol_paths = Vec::new();
    for p in blob_paths {
        let bytes = std::fs::read(p)?;
        let blob =
            BlobRef::new(&bytes).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
        let manifest = blob
            .manifest()
            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
        let dir = blobs_root.join(&manifest.plugin_id);
        std::fs::create_dir_all(&dir)?;
        let file_name = p
            .file_name()
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "blob path has no name"))?;
        std::fs::copy(p, dir.join(file_name))?;
        total += bytes.len() as u64;
        subvol_paths.push(format!("blobs/{}", manifest.plugin_id));
        index.push(serde_json::json!({
            "plugin_id": manifest.plugin_id,
            "schema_version": manifest.schema_version,
            "schema_hash": manifest.schema_hash,
            "dbus_path": manifest.dbus.object_path,
            "services": manifest.grpc.services,
            "file": format!("blobs/{}/{}", manifest.plugin_id, file_name.to_string_lossy()),
        }));
    }
    std::fs::write(
        staging.join("blob-index.json"),
        serde_json::to_vec_pretty(&serde_json::json!({
            "format": "opdbus-blob-image/1",
            "blobs": index,
        }))?,
    )?;

    // Pre-size the image; --shrink trims it to minimal afterwards.
    let size = (total * 2 + 32 * 1024 * 1024).max(64 * 1024 * 1024);
    if image_path.exists() {
        std::fs::remove_file(image_path)?;
    }
    let f = std::fs::File::create(image_path)?;
    f.set_len(size)?;
    drop(f);

    // Try one-subvolume-per-plugin first (btrfs-progs >= 6.x --subvol),
    // fall back to plain directories. `-f`: we own the just-created image, and
    // without it mkfs aborts when any loop device's backing file is
    // unreadable (e.g. root-owned incus disks) during its mount-status scan.
    let mut subvolumes = true;
    let mut args: Vec<String> = vec![
        "-q".into(),
        "-f".into(),
        "--rootdir".into(),
        staging.to_string_lossy().into_owned(),
        "--shrink".into(),
    ];
    for sv in &subvol_paths {
        args.push("--subvol".into());
        args.push(sv.clone());
    }
    args.push(image_path.to_string_lossy().into_owned());
    let ok = run_mkfs(&args)?;
    if !ok {
        subvolumes = false;
        let args: Vec<String> = vec![
            "-q".into(),
            "-f".into(),
            "--rootdir".into(),
            staging.to_string_lossy().into_owned(),
            "--shrink".into(),
            image_path.to_string_lossy().into_owned(),
        ];
        if !run_mkfs(&args)? {
            let _ = std::fs::remove_dir_all(&staging);
            return Err(io::Error::other("mkfs.btrfs failed"));
        }
    }
    let _ = std::fs::remove_dir_all(&staging);

    if !verify_btrfs_image(image_path)? {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "image missing btrfs superblock magic",
        ));
    }

    let image_bytes = std::fs::metadata(image_path)?.len();
    Ok(BtrfsImageReport {
        mount_hint: format!(
            "mount -o loop,ro {} /mnt/opdbus-blob   # then ActiveReflectionCatalog::open(\"/mnt/opdbus-blob/blobs/<plugin>\")",
            image_path.display()
        ),
        image_path: image_path.to_path_buf(),
        image_bytes,
        blob_count: blob_paths.len(),
        subvolumes,
    })
}

/// Check the btrfs superblock magic without mounting or external tools.
pub fn verify_btrfs_image(path: &Path) -> io::Result<bool> {
    use std::io::{Read, Seek, SeekFrom};
    let mut f = std::fs::File::open(path)?;
    if f.metadata()?.len() < BTRFS_MAGIC_OFFSET + 8 {
        return Ok(false);
    }
    f.seek(SeekFrom::Start(BTRFS_MAGIC_OFFSET))?;
    let mut buf = [0u8; 8];
    f.read_exact(&mut buf)?;
    Ok(&buf == BTRFS_MAGIC)
}

pub fn which_mkfs() -> Option<PathBuf> {
    std::env::var_os("PATH").and_then(|paths| {
        std::env::split_paths(&paths)
            .map(|d| d.join("mkfs.btrfs"))
            .find(|p| p.is_file())
    })
}

fn run_mkfs(args: &[String]) -> io::Result<bool> {
    let out = Command::new("mkfs.btrfs").args(args).output()?;
    if !out.status.success() {
        // Caller decides whether to retry without --subvol.
        return Ok(false);
    }
    Ok(true)
}

fn staging_dir(image_path: &Path) -> io::Result<PathBuf> {
    let parent = image_path.parent().unwrap_or(Path::new("."));
    let dir = parent.join(format!(
        ".opblob-staging-{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0)
    ));
    if dir.exists() {
        std::fs::remove_dir_all(&dir)?;
    }
    std::fs::create_dir_all(&dir)?;
    Ok(dir)
}

//! # op-blob — schema-driven plugin object blobs
//!
//! Implements the pipeline defined in
//! `.kiro/specs/schemars-to-reflection-plugin-pipeline/` and the
//! schema-coupled-plugin-blob-reflection whitepaper:
//!
//! ```text
//! Rust state/input/output structs (#[derive(schemars::JsonSchema)])
//!   -> schemars JSON Schema 2020-12
//!   -> adapter::plugin_schema_from_json
//!   -> PluginSchema                      <- SINGLE SOURCE OF TRUTH
//!   -> blob::blobify
//!   -> PluginObjectBlob                  <- sealed projection: schema + metadata
//!        schema_json + schema_hash
//!        D-Bus identity (/org/opdbus/v1/plugins/<name>)
//!        gRPC identity + FileDescriptorSet (typed, per-method)
//!        method manifest (subid, capability, side_effect, idempotent)
//!   -> catalog::ActiveReflectionCatalog  <- /dev/shm/opdbus/plugin-blobs/<id>.<hash>.blob
//!   -> btrfs::seal_blobs_into_btrfs_image <- btrfs filesystem in the blob artifact
//! ```
//!
//! Non-negotiable rules carried over from the whitepaper:
//! 1. `PluginSchema` is the source of truth. The blob is a frozen projection,
//!    never a second source.
//! 2. The plugin owns its schema; schemars is the derivation tool, not the
//!    published contract.
//! 3. Blobs are per-object artifacts (one plugin, one blob, one schema hash),
//!    replacing the monolithic `/dev/shm/live-schema.json` runtime shape.
//! 4. Reflection advertises only active blobs; descriptors are synthesized
//!    from `MethodDecl.args/returns` — no phantom services.
//! 5. Zero-copy: a sealed blob is a sectioned byte image; `BlobRef` hands out
//!    borrowed slices (schema JSON, manifest, descriptor bytes) without
//!    re-parsing or re-allocating on the read path.
//!
//! Divergences from the full workspace (documented, deliberate):
//! - The local `PluginSchema` is a reduced WORKING VIEW used only for
//!   descriptor/manifest synthesis. Real plugins are sealed through
//!   `blobify_plugin_schema`, which seals the FULL canonical
//!   `op_state_store::PluginSchema` JSON (signals, guarantees, category, …);
//!   read it back with `BlobRef::state_store_schema`.
//! - Descriptor bytes are hand-encoded protobuf (`descriptor.rs`) instead of
//!   prost — keeps the crate dependency-free per NFR-3's spirit.

pub mod adapter;
pub mod blob;
pub mod btrfs;
pub mod catalog;
pub mod demo;
pub mod descriptor;
pub mod identity;
pub mod schema;
pub mod subid;

pub use adapter::{
    apply_state_defaults, method_decl_from_schemars_with_output, plugin_schema_from_json,
    schema_diffs, AckOutput, EmptyInput,
};
pub use blob::{
    blobify, blobify_with_identity, canonical_plugin_id, BlobManifest, BlobRef, DbusIdentity,
    GrpcIdentity, MethodManifest, PluginObjectBlob,
};
pub use catalog::{ActiveReflectionCatalog, BlobStore};
pub use identity::{BlobIdentity, WgKeypair};
pub use schema::{Constraint, FieldSchema, FieldType, MethodDecl, PluginSchema, SideEffect};
pub use subid::validate_subid;

pub type BlobMethod = MethodManifest;
pub type DbusObjectIdentity = DbusIdentity;
pub type GrpcObjectIdentity = GrpcIdentity;

pub fn blobify_plugin_schema(
    plugin_id: &str,
    schema: op_state_store::PluginSchema,
) -> PluginObjectBlob {
    blobify_plugin_schema_with_identity(plugin_id, schema, None)
}

/// Seal the FULL canonical workspace schema. The sealed SCHEMA_JSON section
/// (and the schema hash) is the complete `op_state_store::PluginSchema` —
/// signals, guarantees, category and all. The reduced local `PluginSchema` is
/// derived from the same canonical value purely as the working view for
/// descriptor/manifest synthesis; it is never what gets sealed.
pub fn blobify_plugin_schema_with_identity(
    plugin_id: &str,
    mut schema: op_state_store::PluginSchema,
    identity: Option<BlobIdentity>,
) -> PluginObjectBlob {
    schema.name = blob::canonical_plugin_id(plugin_id);
    let canonical_value =
        serde_json::to_value(&schema).expect("op-state-store PluginSchema serializes");
    // serde_json's Map is BTreeMap-backed (no `preserve_order`), so this is
    // deterministic key-sorted canonical JSON.
    let canonical_json =
        serde_json::to_string(&canonical_value).expect("canonical value serializes");
    let working: PluginSchema = serde_json::from_value(canonical_value)
        .expect("op-blob PluginSchema view accepts op-state-store schema");
    blob::blobify_canonical(&working, canonical_json, identity)
}

[package]
name = "op-blob"
version.workspace = true
edition.workspace = true
authors.workspace = true
license.workspace = true
description = "Schema-driven plugin object blobs: schemars struct -> PluginSchema (single source of truth) -> sealed zero-copy blob (schema + D-Bus/gRPC identity + reflection descriptors + OSCAL metadata) -> active reflection catalog -> btrfs filesystem image"

[dependencies]
op-state-store = { workspace = true }
serde = { workspace = true }
# NOTE: serde_json without `preserve_order` backs Map with BTreeMap — key-sorted
# serialization is what makes PluginSchema::canonical_json deterministic.
serde_json = { workspace = true }
simd-json = { workspace = true }
schemars = "1"
sha2 = { workspace = true }
blake3 = { workspace = true }
hex = { workspace = true }
# WireGuard keypair is the identity: WG keys are X25519 keys.
x25519-dalek = { version = "2", features = ["static_secrets"] }
rand_core = { version = "0.6", features = ["getrandom"] }

//! `ActiveReflectionCatalog` — the bridge-owned mutable layer that
//! tonic-reflection's immutable `Builder` cannot be (whitepaper: "Why
//! tonic-reflection Builder Is Not Enough").
//!
//! The catalog owns active plugin blobs and answers reflection queries:
//! `list_services` advertises only active blobs (no phantom services);
//! `file_by_filename` / `symbol_by_name` serve borrowed descriptor bytes
//! sliced straight out of the sealed blob images (zero-copy).
//!
//! Persistence is the per-object shm layout that replaces monolithic
//! `/dev/shm/live-schema.json`:
//!
//! ```text
//! /dev/shm/opdbus/plugin-blobs/<plugin_id>.<schema_hash16>.blob
//! ```

use crate::blob::{BlobManifest, BlobRef, PluginObjectBlob};
use crate::descriptor;
use std::collections::HashMap;
use std::io;
use std::path::{Path, PathBuf};

pub const DEFAULT_SHM_DIR: &str = "/dev/shm/opdbus/plugin-blobs";

/// Catalog manifest filename — the atomic commit point of the blob dir.
/// `{ catalog_hash, generation, plugins: { <plugin_id>: <schema_hash> } }`.
/// `catalog_hash` is a blake3 leaf-fold over the sorted per-blob schema
/// hashes; it is computed HERE and only here — consumers read it, never
/// re-hash (one-schema rule).
pub const MANIFEST_FILENAME: &str = ".manifest.json";

struct Entry {
    path: PathBuf,
    /// Sealed blob image; descriptor lookups return subslices of this.
    bytes: Vec<u8>,
    manifest: BlobManifest,
    /// file name -> (offset, len) of the FileDescriptorProto within `bytes`.
    files: HashMap<String, (usize, usize)>,
    /// fully-qualified symbol -> file name.
    symbols: HashMap<String, String>,
}

pub struct ActiveReflectionCatalog {
    dir: PathBuf,
    entries: HashMap<String, Entry>,
}

/// Durable blob store. It keeps the historical `BlobStore` name while allowing
/// typed blob families in one store namespace. Today the active-reflection
/// family is backed by `ActiveReflectionCatalog`.
pub struct BlobStore {
    active_reflection: ActiveReflectionCatalog,
}

impl BlobStore {
    pub fn open(dir: impl Into<PathBuf>) -> io::Result<Self> {
        Ok(Self {
            active_reflection: ActiveReflectionCatalog::open(dir)?,
        })
    }

    pub fn open_default() -> io::Result<Self> {
        Self::open(DEFAULT_SHM_DIR)
    }

    pub fn write(&mut self, blob: &PluginObjectBlob) -> io::Result<PathBuf> {
        match blob.manifest.blob_type.as_str() {
            "active_reflection" => self.active_reflection.upsert_blob(blob),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unsupported blob type: {other}"),
            )),
        }
    }

    pub fn remove_blob(&mut self, plugin_id: &str) -> io::Result<bool> {
        self.active_reflection.remove_blob(plugin_id)
    }

    pub fn retain_plugins(
        &mut self,
        keep: &std::collections::HashSet<String>,
    ) -> io::Result<Vec<String>> {
        self.active_reflection.retain_plugins(keep)
    }

    pub fn catalog_hash(&self) -> String {
        self.active_reflection.catalog_hash()
    }

    pub fn list_services(&self) -> Vec<String> {
        self.active_reflection.list_services()
    }

    pub fn active_plugins(&self) -> Vec<String> {
        self.active_reflection.active_plugins()
    }

    pub fn manifest(&self, plugin_id: &str) -> Option<&BlobManifest> {
        self.active_reflection.manifest(plugin_id)
    }

    pub fn blob_paths(&self) -> Vec<PathBuf> {
        self.active_reflection.blob_paths()
    }

    pub fn plugin_object_blobs(&self) -> Vec<PluginObjectBlob> {
        self.active_reflection.plugin_object_blobs()
    }

    pub fn active_reflection(&self) -> &ActiveReflectionCatalog {
        &self.active_reflection
    }
}

impl ActiveReflectionCatalog {
    /// Open (and create) a catalog directory, loading any existing blobs.
    pub fn open(dir: impl Into<PathBuf>) -> io::Result<Self> {
        let dir = dir.into();
        std::fs::create_dir_all(&dir)?;
        let mut cat = Self {
            dir: dir.clone(),
            entries: HashMap::new(),
        };
        for e in std::fs::read_dir(&dir)? {
            let path = e?.path();
            if path.extension().and_then(|x| x.to_str()) == Some("blob") {
                if let Err(err) = cat.load_file(&path) {
                    // A corrupt blob must not take the catalog down; it is
                    // simply not advertised.
                    eprintln!("op-blob: skipping {}: {err}", path.display());
                }
            }
        }
        Ok(cat)
    }

    /// Default runtime location on tmpfs (REQ-8.3: never Btrfs-backed I/O).
    pub fn open_shm() -> io::Result<Self> {
        Self::open(DEFAULT_SHM_DIR)
    }

    fn load_file(&mut self, path: &Path) -> Result<(), String> {
        let bytes = std::fs::read(path).map_err(|e| e.to_string())?;
        let entry = index_entry(path.to_path_buf(), bytes)?;
        self.entries.insert(entry.manifest.plugin_id.clone(), entry);
        Ok(())
    }

    /// Whitepaper lifecycle steps 10–12: persist the sealed blob, drop stale
    /// hash versions of the same plugin, rebuild the reflection index, and
    /// commit the catalog manifest.
    pub fn upsert_blob(&mut self, blob: &PluginObjectBlob) -> io::Result<PathBuf> {
        let path = blob.write_to_dir(&self.dir)?;
        // Remove superseded hash versions on disk.
        let prefix = format!("{}.", blob.manifest.plugin_id);
        for e in std::fs::read_dir(&self.dir)? {
            let p = e?.path();
            if p != path {
                if let Some(name) = p.file_name().and_then(|n| n.to_str()) {
                    if name.starts_with(&prefix) && name.ends_with(".blob") {
                        let _ = std::fs::remove_file(&p);
                    }
                }
            }
        }
        let bytes = std::fs::read(&path)?;
        let entry = index_entry(path.clone(), bytes)
            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
        self.entries.insert(blob.manifest.plugin_id.clone(), entry);
        self.write_manifest()?;
        Ok(path)
    }

    /// Inverse lifecycle: deactivate the plugin object, delete the artifact,
    /// stop advertising its services, commit the catalog manifest.
    pub fn remove_blob(&mut self, plugin_id: &str) -> io::Result<bool> {
        match self.entries.remove(plugin_id) {
            Some(entry) => {
                if entry.path.exists() {
                    std::fs::remove_file(&entry.path)?;
                }
                self.write_manifest()?;
                Ok(true)
            }
            None => Ok(false),
        }
    }

    /// Drop every blob whose plugin id is NOT in `keep`. Returns the removed
    /// plugin ids. This is how a full re-seal deregisters plugins that no
    /// longer exist — a blob in the catalog IS the plugin, so a plugin that
    /// vanished from the build must vanish from the catalog.
    pub fn retain_plugins(&mut self, keep: &std::collections::HashSet<String>) -> io::Result<Vec<String>> {
        let stale: Vec<String> = self
            .entries
            .keys()
            .filter(|id| !keep.contains(*id))
            .cloned()
            .collect();
        for id in &stale {
            if let Some(entry) = self.entries.remove(id) {
                if entry.path.exists() {
                    std::fs::remove_file(&entry.path)?;
                }
            }
        }
        if !stale.is_empty() {
            self.write_manifest()?;
        }
        Ok(stale)
    }

    /// Blake3 leaf-fold over the sorted `(plugin_id, schema_hash)` pairs —
    /// the single catalog identity value.
    pub fn catalog_hash(&self) -> String {
        let mut leaves: Vec<(&String, &String)> = self
            .entries
            .iter()
            .map(|(id, e)| (id, &e.manifest.schema_hash))
            .collect();
        leaves.sort();
        let mut h = blake3::Hasher::new();
        for (id, hash) in leaves {
            h.update(id.as_bytes());
            h.update(b"\0");
            h.update(hash.as_bytes());
            h.update(b"\0");
        }
        h.finalize().to_hex().to_string()
    }

    /// Write `.manifest.json` atomically (tmp + rename), LAST after blob
    /// mutations — the commit point consumers use for change detection.
    fn write_manifest(&self) -> io::Result<()> {
        let path = self.dir.join(MANIFEST_FILENAME);
        let generation = Self::read_manifest_generation(&path).wrapping_add(1);
        let mut plugins = std::collections::BTreeMap::new();
        for (id, e) in &self.entries {
            plugins.insert(id.clone(), e.manifest.schema_hash.clone());
        }
        let manifest = serde_json::json!({
            "catalog_hash": self.catalog_hash(),
            "generation": generation,
            "plugins": plugins,
        });
        let bytes = serde_json::to_vec_pretty(&manifest)
            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
        let tmp = self.dir.join(format!("{MANIFEST_FILENAME}.tmp"));
        std::fs::write(&tmp, &bytes)?;
        std::fs::rename(&tmp, &path)?;
        Ok(())
    }

    /// Current manifest `generation`, or 0 if absent/unparsable. The next
    /// write uses `generation + 1` so readers get a monotonic staleness marker.
    fn read_manifest_generation(path: &Path) -> u64 {
        std::fs::read(path)
            .ok()
            .and_then(|b| serde_json::from_slice::<serde_json::Value>(&b).ok())
            .and_then(|v| v.get("generation").and_then(serde_json::Value::as_u64))
            .unwrap_or(0)
    }

    /// Read the published `catalog_hash` from a catalog dir without loading
    /// any blobs. Consumers use this for arrival-triggered change detection —
    /// read, never re-hash.
    pub fn read_catalog_hash(dir: &Path) -> Option<String> {
        let bytes = std::fs::read(dir.join(MANIFEST_FILENAME)).ok()?;
        let v: serde_json::Value = serde_json::from_slice(&bytes).ok()?;
        v.get("catalog_hash")
            .and_then(serde_json::Value::as_str)
            .map(String::from)
    }

    /// Reflection `ListServices`: only active blobs, sorted.
    pub fn list_services(&self) -> Vec<String> {
        let mut v: Vec<String> = self
            .entries
            .values()
            .flat_map(|e| e.manifest.grpc.services.iter().cloned())
            .collect();
        v.sort();
        v
    }

    pub fn active_plugins(&self) -> Vec<String> {
        let mut v: Vec<String> = self.entries.keys().cloned().collect();
        v.sort();
        v
    }

    /// Reflection `file_by_filename`: borrowed `FileDescriptorProto` bytes.
    pub fn file_by_filename(&self, filename: &str) -> Option<&[u8]> {
        self.entries.values().find_map(|e| {
            e.files
                .get(filename)
                .map(|(off, len)| &e.bytes[*off..*off + *len])
        })
    }

    /// Reflection `file_containing_symbol`.
    pub fn symbol_by_name(&self, symbol: &str) -> Option<&[u8]> {
        self.entries.values().find_map(|e| {
            e.symbols
                .get(symbol)
                .and_then(|file| e.files.get(file))
                .map(|(off, len)| &e.bytes[*off..*off + *len])
        })
    }

    pub fn manifest(&self, plugin_id: &str) -> Option<&BlobManifest> {
        self.entries.get(plugin_id).map(|e| &e.manifest)
    }

    pub fn dir(&self) -> &Path {
        &self.dir
    }

    /// Paths of all active blob artifacts (input to btrfs sealing).
    pub fn blob_paths(&self) -> Vec<PathBuf> {
        let mut v: Vec<PathBuf> = self.entries.values().map(|e| e.path.clone()).collect();
        v.sort();
        v
    }

    /// Rehydrate every active blob as an owned `PluginObjectBlob`, sorted by
    /// plugin id — the startup-hydration input for in-memory reflection.
    pub fn plugin_object_blobs(&self) -> Vec<PluginObjectBlob> {
        let mut ids: Vec<&String> = self.entries.keys().collect();
        ids.sort();
        ids.iter()
            .filter_map(|id| PluginObjectBlob::from_sealed(&self.entries[*id].bytes).ok())
            .collect()
    }
}

/// Read ONE plugin's canonical schema straight from its sealed blob in `dir`
/// — the single-plugin read path (no catalog load, no monolith file). This is
/// how a component (including a plugin reading its own contract) asks "what
/// is plugin X": the blob answers, nothing else does.
pub fn read_plugin_state_store_schema(
    dir: &Path,
    plugin_id: &str,
) -> Option<op_state_store::PluginSchema> {
    let prefix = format!("{plugin_id}.");
    for e in std::fs::read_dir(dir).ok()? {
        let p = e.ok()?.path();
        let Some(name) = p.file_name().and_then(|n| n.to_str()) else {
            continue;
        };
        if name.starts_with(&prefix) && name.ends_with(".blob") {
            let bytes = std::fs::read(&p).ok()?;
            let blob = BlobRef::new(&bytes).ok()?;
            return blob.state_store_schema().ok();
        }
    }
    None
}

/// [`read_plugin_state_store_schema`] against the default SHM catalog.
pub fn read_plugin_schema_shm(plugin_id: &str) -> Option<op_state_store::PluginSchema> {
    read_plugin_state_store_schema(Path::new(DEFAULT_SHM_DIR), plugin_id)
}

/// The active plugin ids from the catalog manifest (sorted) — the cheap
/// "which plugins exist" read: one small JSON file, no blob loads.
pub fn read_manifest_plugin_ids(dir: &Path) -> Option<Vec<String>> {
    let bytes = std::fs::read(dir.join(MANIFEST_FILENAME)).ok()?;
    let v: serde_json::Value = serde_json::from_slice(&bytes).ok()?;
    let mut ids: Vec<String> = v.get("plugins")?.as_object()?.keys().cloned().collect();
    ids.sort();
    Some(ids)
}

/// [`read_manifest_plugin_ids`] against the default SHM catalog.
pub fn read_manifest_plugin_ids_shm() -> Option<Vec<String>> {
    read_manifest_plugin_ids(Path::new(DEFAULT_SHM_DIR))
}

fn index_entry(path: PathBuf, bytes: Vec<u8>) -> Result<Entry, String> {
    let (manifest, files) = {
        let blob = BlobRef::new(&bytes)?;
        let manifest = blob.manifest()?;
        let set = blob.descriptor_set();
        let set_start = set.as_ptr() as usize - bytes.as_ptr() as usize;
        let mut files = HashMap::new();
        for f in descriptor::decode_file_summaries(set)? {
            let off = f.bytes.as_ptr() as usize - set.as_ptr() as usize;
            files.insert(f.name.clone(), (set_start + off, f.bytes.len()));
        }
        (manifest, files)
    };
    let mut symbols = HashMap::new();
    for m in &manifest.methods {
        for s in &m.symbols {
            symbols.insert(s.clone(), m.grpc_file.clone());
        }
    }
    Ok(Entry {
        path,
        bytes,
        manifest,
        files,
        symbols,
    })
}

//! Reference plugins proving "the plugin is the schema pipeline" end-to-end.
//!
//! `unix_socket` mirrors the spec's canonical Tier-A pattern
//! (`op-plugins/src/state_plugins/unix_socket.rs`): the state struct and every
//! method input/output struct derive `schemars::JsonSchema`; the schema
//! function is `plugin_schema_from_json` + `apply_state_defaults` + typed
//! method inserts. `wireguard` is the identity-bearing first-pass plugin from
//! the whitepaper.

use crate::adapter::{
    apply_state_defaults, method_decl_from_schemars_with_output, plugin_schema_from_json, AckOutput,
};
use crate::schema::{PluginSchema, SideEffect};
use serde::{Deserialize, Serialize};

// ---------------------------------------------------------------------------
// unix_socket — canonical Tier-A pattern
// ---------------------------------------------------------------------------

/// One declared socket endpoint.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct SocketEndpoint {
    /// Filesystem path of the unix socket
    pub path: String,
    /// Abstract port tag for socket multiplexing
    #[schemars(range(min = 1, max = 65535))]
    pub port: u16,
}

/// The state struct IS the schema (spec Layer 0).
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.network.unix-socket.describe@v1"))]
pub struct UnixSocketState {
    /// Declared socket endpoints
    #[schemars(extend("x-oscal-subid" = "obs.network.unix-socket.endpoints@v1"))]
    pub sockets: Vec<SocketEndpoint>,
}

#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct BindInput {
    /// Socket path to bind
    pub path: String,
    /// Port tag to register
    pub port: u16,
}

#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct CloseInput {
    /// Socket path to close
    pub path: String,
}

/// Canonical schema function: derivation, defaults, then typed methods.
pub fn unix_socket_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(UnixSocketState))
        .expect("schemars serializes cleanly");
    let mut schema = plugin_schema_from_json(
        "unix_socket",
        "1.0.0",
        "Unix domain socket ownership and registration",
        &root,
    );
    let defaults = serde_json::to_value(UnixSocketState::default()).expect("default serializes");
    apply_state_defaults(&mut schema, &defaults);

    // Method-level subid with no struct field: the one sanctioned imperative
    // insert (REQ-3.4).
    schema.subids.insert(
        "bind".to_string(),
        "mut.network.unix-socket.bind@v1".to_string(),
    );

    schema.methods.insert(
        "bind".to_string(),
        method_decl_from_schemars_with_output::<BindInput, AckOutput>(
            "bind",
            SideEffect::Mutation,
            false,
            "unix_socket.write",
            "mut.network.unix-socket.bind@v1",
        ),
    );
    schema.methods.insert(
        "close".to_string(),
        method_decl_from_schemars_with_output::<CloseInput, AckOutput>(
            "close",
            SideEffect::Mutation,
            true,
            "unix_socket.write",
            "mut.network.unix-socket.close@v1",
        ),
    );
    schema
}

