usage() {
    cat <<'EOF'
zcall - short wrapper for blob-created opdbus plugin calls

Usage:
  zcall list
  zcall methods <plugin>
  zcall help [plugin] [method]
  zcall expand <plugin> <method> [--arguments JSON]
  zcall <plugin> <method> --arguments JSON

Options:
  -a, --arguments JSON      JSON argument list. Arrays are passed as repeated
                            arguments; objects/scalars are wrapped as one arg.
  -c, --capability ID       Capability id for PluginService.CallMethod.
      --actor ID            Actor id for PluginService.CallMethod.
      --object PATH         Override object path.
      --interface NAME      Override interface name.
      --endpoint HOST:PORT  gRPC endpoint. Default: 127.0.0.1:8090.
      --blob-dir DIR        Blob catalog. Default: /dev/shm/opdbus/plugin-blobs.
      --source MODE         blob, auto, schema, dbus. Default: blob.
      --print               Print the expanded grpcurl command and request.
  -h, --help                Show help.

Examples:
  zcall methods unix_socket
  zcall help unix_socket bind
  zcall unix_socket bind --arguments '{"name":"qdrant","path":"/run/qdrant.sock","ports":[6333,6334]}'
  zcall expand qdrant create_collection --arguments '{"collection_name":"docs"}'

By default zcall parses sealed blobs in /dev/shm/opdbus/plugin-blobs. It does
not need D-Bus introspection for list/help/completion.
EOF
}

die() {
    printf 'zcall: %s\n' "$*" >&2
    exit 1
}

have() {
    command -v "$1" >/dev/null 2>&1
}

normalize_plugin() {
    printf '%s' "${1//-/_}"
}

normalize_method() {
    printf '%s' "${1//-/_}"
}

contract_py() {
    python3 - "$@" <<'PY'
import ast
import json
import os
import re
import struct
import subprocess
import sys

MAGIC = b"OPBLOB01"
HEADER_LEN = 64
ENTRY_LEN = 24
SECTION_SCHEMA = 1
SECTION_MANIFEST = 2
DBUS_SERVICE = os.environ.get("ZCALL_DBUS_SERVICE", "org.opdbus.v1.plugins")
DBUS_BASE_PATH = os.environ.get("ZCALL_DBUS_BASE_PATH", "/org/opdbus/v1/plugins")
DBUS_IFACE = os.environ.get("ZCALL_DBUS_IFACE", "org.opdbus.v1.plugins.ProjectedObject")


def canonical_method_name(name):
    name = re.sub(r"(.)([A-Z][a-z]+)", r"\1_\2", str(name))
    name = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", name)
    return name.replace("-", "_").lower()


def read_blob(path):
    data = open(path, "rb").read()
    if len(data) < HEADER_LEN or data[:8] != MAGIC:
        return None
    section_count = struct.unpack_from("<H", data, 10)[0]
    sections = {}
    for i in range(section_count):
        pos = HEADER_LEN + i * ENTRY_LEN
        if pos + ENTRY_LEN > len(data):
            break
        tag, _reserved, off, size = struct.unpack_from("<IIQQ", data, pos)
        if off + size <= len(data):
            sections[tag] = data[off:off + size]
    manifest = json.loads(sections.get(SECTION_MANIFEST, b"{}") or b"{}")
    schema = json.loads(sections.get(SECTION_SCHEMA, b"{}") or b"{}")
    return {"manifest": manifest, "schema": schema}


def blob_records(blob_dir):
    records = {}
    if not os.path.isdir(blob_dir):
        return records
    for name in sorted(os.listdir(blob_dir)):
        if not name.endswith(".blob"):
            continue
        path = os.path.join(blob_dir, name)
        try:
            rec = read_blob(path)
        except Exception:
            continue
        if not rec:
            continue
        plugin = rec["manifest"].get("plugin_id") or rec["schema"].get("name")
        if plugin:
            records[str(plugin)] = rec
    return records


def live_schema_records():
    path = "/dev/shm/live-schema.json"
    if not os.path.exists(path):
        return {}
    try:
        root = json.load(open(path))
    except Exception:
        return {}
    if not isinstance(root, dict):
        return {}
    records = {}
    for plugin, value in root.items():
        schema = value[0] if isinstance(value, list) and value else value
        if isinstance(schema, dict):
            records[str(plugin)] = {"manifest": {}, "schema": schema}
    return records


def parse_busctl_string(raw):
    raw = raw.strip()
    if raw.startswith("s "):
        raw = raw[2:].strip()
    if raw.startswith('"'):
        return ast.literal_eval(raw)
    return raw


def dbus_methods(plugin):
    path = f"{DBUS_BASE_PATH}/{plugin}"
    try:
        raw = subprocess.check_output(
            [
                "busctl",
                "--system",
                "get-property",
                DBUS_SERVICE,
                path,
                DBUS_IFACE,
                "Methods",
            ],
            stderr=subprocess.DEVNULL,
            text=True,
        )
        text = parse_busctl_string(raw)
        value = json.loads(text)
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def dbus_plugins():
    try:
        raw = subprocess.check_output(
            ["busctl", "--system", "tree", DBUS_SERVICE],
            stderr=subprocess.DEVNULL,
            text=True,
        )
    except Exception:
        return []
    plugins = []
    prefix = f"{DBUS_BASE_PATH}/"
    for line in raw.splitlines():
        line = line.strip()
        idx = line.find(prefix)
        if idx < 0:
            continue
        rest = line[idx + len(prefix):].strip()
        if rest and "/" not in rest:
            plugins.append(rest)
    return sorted(set(plugins))


def schema_methods(schema):
    methods = schema.get("methods") if isinstance(schema, dict) else {}
    return methods if isinstance(methods, dict) else {}


def manifest_methods(manifest):
    methods = {}
    for item in manifest.get("methods", []) if isinstance(manifest, dict) else []:
        if not isinstance(item, dict):
            continue
        name = item.get("schema_name") or item.get("name")
        if name:
            methods[canonical_method_name(name)] = item
    return methods


def callable_records(records):
    out = {}
    for plugin, rec in records.items():
        methods = manifest_methods(rec.get("manifest", {}))
        methods.update(schema_methods(rec.get("schema", {})))
        if methods:
            out[plugin] = rec
    return out


def records_for(source, blob_dir):
    if source in ("auto", "blob"):
        recs = blob_records(blob_dir)
        if recs or source == "blob":
            return recs
    if source in ("auto", "schema"):
        recs = live_schema_records()
        if recs or source == "schema":
            return recs
    return {}


def methods_for(plugin, source, blob_dir):
    recs = records_for(source, blob_dir)
    rec = recs.get(plugin)
    if rec:
        methods = schema_methods(rec.get("schema", {}))
        for name, item in manifest_methods(rec.get("manifest", {})).items():
            if isinstance(methods.get(name), dict) and isinstance(item, dict):
                merged = dict(item)
                merged.update(methods[name])
                methods[name] = merged
            else:
                methods[name] = item
        return methods
    if source in ("auto", "dbus"):
        return dbus_methods(plugin)
    return {}


def plugins_for(source, blob_dir):
    recs = records_for(source, blob_dir)
    if recs:
        return sorted(recs)
    if source in ("auto", "dbus"):
        return dbus_plugins()
    return []


def completion_plugins_for(source, blob_dir):
    recs = records_for(source, blob_dir)
    if recs:
        return sorted(p.replace("_", "-") for p in callable_records(recs))
    if source in ("auto", "dbus"):
        return sorted(p.replace("_", "-") for p in dbus_plugins() if dbus_methods(p))
    return []


def plugin_identity(plugin, source, blob_dir):
    recs = records_for(source, blob_dir)
    rec = recs.get(plugin, {})
    manifest = rec.get("manifest", {})
    dbus = manifest.get("dbus", {}) if isinstance(manifest, dict) else {}
    return {
        "object_path": dbus.get("object_path") or f"{DBUS_BASE_PATH}/{plugin}",
        "interface_name": dbus.get("interface_name") or "org.opdbus.v1.Plugin",
    }


def method_detail(methods, name):
    if name in methods:
        return methods[name]
    lowered = name.lower()
    for key, val in methods.items():
        if key.lower() == lowered:
            return val
        if isinstance(val, dict) and str(val.get("name", "")).lower() == lowered:
            return val
    return None


def arg_flags_for(plugin, method, source, blob_dir):
    detail = method_detail(methods_for(plugin, source, blob_dir), method)
    if not isinstance(detail, dict):
        return []
    args = detail.get("args")
    if not isinstance(args, dict):
        return []
    props = args.get("properties")
    if not isinstance(props, dict):
        return []
    return [f"--{name.replace('_', '-')}" for name in sorted(props)]


cmd = sys.argv[1]
source = sys.argv[2]
blob_dir = sys.argv[3]

if cmd == "plugins":
    print("\n".join(plugins_for(source, blob_dir)))
elif cmd == "completion-plugins":
    print("\n".join(completion_plugins_for(source, blob_dir)))
elif cmd == "methods":
    plugin = sys.argv[4]
    print("\n".join(m.replace("_", "-") for m in sorted(methods_for(plugin, source, blob_dir))))
elif cmd == "method-json":
    plugin, method = sys.argv[4], sys.argv[5]
    detail = method_detail(methods_for(plugin, source, blob_dir), method)
    print(json.dumps(detail or {}, indent=2, sort_keys=True))
elif cmd == "args":
    plugin, method = sys.argv[4], sys.argv[5]
    print("\n".join(arg_flags_for(plugin, method, source, blob_dir)))
elif cmd == "method-summary":
    plugin = sys.argv[4]
    methods = methods_for(plugin, source, blob_dir)
    for key in sorted(methods):
        val = methods[key]
        if isinstance(val, dict):
            display = val.get("name") or key
            cap = val.get("required_capability") or "-"
            side = val.get("side_effect") or "-"
            subid = val.get("subid") or "-"
            print(f"{display}\t{side}\t{cap}\t{subid}")
        else:
            print(f"{key}\t-\t-\t-")
elif cmd == "identity":
    plugin = sys.argv[4]
    print(json.dumps(plugin_identity(plugin, source, blob_dir), sort_keys=True))
else:
    raise SystemExit(f"unknown contract command: {cmd}")
PY
}

read_headers() {
    python3 - "$SLED_PATH" <<'PY'
import os
import sys

path = sys.argv[1]
try:
    data = open(path, "rb").read()
except Exception:
    raise SystemExit(0)
if len(data) < 88:
    raise SystemExit(0)
footprint = data[40:72]
trace_id = data[72:88]
if not footprint or not trace_id or all(b == 0 for b in footprint) or all(b == 0 for b in trace_id):
    raise SystemExit(0)
print("-H")
print("x-ghostbridge-footprint: " + footprint.hex())
print("-H")
print("x-ghostbridge-trace-id: " + trace_id.hex())
PY
}

request_json() {
    local plugin="$1"
    local method="$2"
    local object="$3"
    local iface="$4"
    python3 - "$plugin" "$method" "$object" "$iface" "$arguments_json" "$actor_id" "$capability_id" <<'PY'
import json
import sys

plugin, method, obj, iface, raw_args, actor, capability = sys.argv[1:]
try:
    parsed = json.loads(raw_args)
except Exception as exc:
    raise SystemExit(f"invalid --arguments JSON: {exc}")
arguments = parsed if isinstance(parsed, list) else [parsed]
print(json.dumps({
    "plugin_id": plugin,
    "object_path": obj,
    "interface_name": iface,
    "method_name": method,
    "arguments": arguments,
    "actor_id": actor,
    "capability_id": capability,
}, separators=(",", ":")))
PY
}

args_json_from_flags() {
    local plugin="$1"
    local method="$2"
    shift 2
    python3 - "$source_mode" "$blob_dir" "$plugin" "$method" "$@" <<'PY'
import ast
import json
import os
import re
import struct
import subprocess
import sys

MAGIC = b"OPBLOB01"
HEADER_LEN = 64
ENTRY_LEN = 24
SECTION_SCHEMA = 1
SECTION_MANIFEST = 2
DBUS_SERVICE = os.environ.get("ZCALL_DBUS_SERVICE", "org.opdbus.v1.plugins")
DBUS_BASE_PATH = os.environ.get("ZCALL_DBUS_BASE_PATH", "/org/opdbus/v1/plugins")
DBUS_IFACE = os.environ.get("ZCALL_DBUS_IFACE", "org.opdbus.v1.plugins.ProjectedObject")


def canonical_method_name(name):
    name = re.sub(r"(.)([A-Z][a-z]+)", r"\1_\2", str(name))
    name = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", name)
    return name.replace("-", "_").lower()


def read_blob(path):
    data = open(path, "rb").read()
    if len(data) < HEADER_LEN or data[:8] != MAGIC:
        return None
    section_count = struct.unpack_from("<H", data, 10)[0]
    sections = {}
    for i in range(section_count):
        pos = HEADER_LEN + i * ENTRY_LEN
        if pos + ENTRY_LEN > len(data):
            break
        tag, _reserved, off, size = struct.unpack_from("<IIQQ", data, pos)
        if off + size <= len(data):
            sections[tag] = data[off:off + size]
    return {
        "manifest": json.loads(sections.get(SECTION_MANIFEST, b"{}") or b"{}"),
        "schema": json.loads(sections.get(SECTION_SCHEMA, b"{}") or b"{}"),
    }


def blob_records(blob_dir):
    records = {}
    if not os.path.isdir(blob_dir):
        return records
    for name in sorted(os.listdir(blob_dir)):
        if not name.endswith(".blob"):
            continue
        try:
            rec = read_blob(os.path.join(blob_dir, name))
        except Exception:
            continue
        if not rec:
            continue
        plugin = rec["manifest"].get("plugin_id") or rec["schema"].get("name")
        if plugin:
            records[str(plugin)] = rec
    return records


def live_schema_records():
    path = "/dev/shm/live-schema.json"
    if not os.path.exists(path):
        return {}
    try:
        root = json.load(open(path))
    except Exception:
        return {}
    records = {}
    for plugin, value in root.items():
        schema = value[0] if isinstance(value, list) and value else value
        if isinstance(schema, dict):
            records[str(plugin)] = {"manifest": {}, "schema": schema}
    return records


def parse_busctl_string(raw):
    raw = raw.strip()
    if raw.startswith("s "):
        raw = raw[2:].strip()
    if raw.startswith('"'):
        return ast.literal_eval(raw)
    return raw


def dbus_methods(plugin):
    try:
        raw = subprocess.check_output(
            ["busctl", "--system", "get-property", DBUS_SERVICE, f"{DBUS_BASE_PATH}/{plugin}", DBUS_IFACE, "Methods"],
            stderr=subprocess.DEVNULL,
            text=True,
        )
        value = json.loads(parse_busctl_string(raw))
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def schema_methods(schema):
    methods = schema.get("methods") if isinstance(schema, dict) else {}
    return methods if isinstance(methods, dict) else {}


def manifest_methods(manifest):
    methods = {}
    for item in manifest.get("methods", []) if isinstance(manifest, dict) else []:
        if isinstance(item, dict):
            name = item.get("schema_name") or item.get("name")
            if name:
                methods[canonical_method_name(name)] = item
    return methods


def records_for(source, blob_dir):
    if source in ("auto", "blob"):
        recs = blob_records(blob_dir)
        if recs or source == "blob":
            return recs
    if source in ("auto", "schema"):
        recs = live_schema_records()
        if recs or source == "schema":
            return recs
    return {}


def methods_for(plugin, source, blob_dir):
    rec = records_for(source, blob_dir).get(plugin)
    if rec:
        methods = schema_methods(rec.get("schema", {}))
        for name, item in manifest_methods(rec.get("manifest", {})).items():
            if isinstance(methods.get(name), dict) and isinstance(item, dict):
                merged = dict(item)
                merged.update(methods[name])
                methods[name] = merged
            else:
                methods[name] = item
        return methods
    if source in ("auto", "dbus"):
        return dbus_methods(plugin)
    return {}


def method_detail(methods, name):
    if name in methods:
        return methods[name]
    lowered = name.lower()
    for key, val in methods.items():
        if key.lower() == lowered:
            return val
        if isinstance(val, dict) and str(val.get("name", "")).lower() == lowered:
            return val
    return {}


def parse_scalar(raw):
    if raw == "":
        return ""
    if raw[0] in "[{\"" or raw in ("true", "false", "null") or raw[0].isdigit() or raw[0] == "-":
        try:
            return json.loads(raw)
        except Exception:
            pass
    return raw


def parse_value(raw, schema):
    typ = schema.get("type") if isinstance(schema, dict) else None
    if isinstance(typ, list):
        typ = next((t for t in typ if t != "null"), typ[0] if typ else None)
    if typ == "array":
        if raw.startswith("["):
            return json.loads(raw)
        item_schema = schema.get("items", {}) if isinstance(schema, dict) else {}
        return [parse_value(part.strip(), item_schema) for part in raw.split(",") if part.strip() != ""]
    if typ == "object":
        return json.loads(raw)
    if typ == "integer":
        return int(raw)
    if typ == "number":
        return float(raw)
    if typ == "boolean":
        if raw.lower() in ("1", "true", "yes", "on"):
            return True
        if raw.lower() in ("0", "false", "no", "off"):
            return False
        raise SystemExit(f"invalid boolean value: {raw}")
    return parse_scalar(raw)


source, blob_dir, plugin, method = sys.argv[1:5]
pairs = sys.argv[5:]
detail = method_detail(methods_for(plugin, source, blob_dir), method)
arg_schema = detail.get("args", {}) if isinstance(detail, dict) else {}
props = arg_schema.get("properties", {}) if isinstance(arg_schema, dict) else {}
obj = {}
for pair in pairs:
    key, raw = pair.split("=", 1)
    key = key.replace("-", "_")
    obj[key] = parse_value(raw, props.get(key, {}))
print(json.dumps(obj, separators=(",", ":")))
PY
}

print_expanded() {
    local request="$1"
    local -a headers=("${@:2}")
    printf 'grpcurl -plaintext'
    local i
    for ((i = 0; i < ${#headers[@]}; i += 2)); do
        printf ' -H %q' "${headers[i + 1]}"
    done
    printf ' -d %q %q %q\n' "$request" "$endpoint" "$SERVICE"
}

complete_mode=0
if [[ "${1:-}" == "--complete" ]]; then
    complete_mode=1
    shift
fi

while (($#)); do
    case "$1" in
        --endpoint)
            endpoint="${2:-}"; shift 2 ;;
        --blob-dir)
            blob_dir="${2:-}"; shift 2 ;;
        --source)
            source_mode="${2:-}"; shift 2 ;;
        -a|--arguments)
            arguments_json="${2:-}"; arguments_was_set=1; shift 2 ;;
        -c|--capability)
            capability_id="${2:-}"; shift 2 ;;
        --actor)
            actor_id="${2:-}"; shift 2 ;;
        --object)
            object_path="${2:-}"; shift 2 ;;
        --interface)
            interface_name="${2:-}"; shift 2 ;;
        --print|--dry-run)
            print_only=1; shift ;;
        -h|--help)
            usage; exit 0 ;;
        --)
            shift; break ;;
        -*)
            die "unknown option: $1" ;;
        *)
            break ;;
    esac
done

if ((complete_mode)); then
    case "${1:-}" in
        plugins) contract_py completion-plugins "$source_mode" "$blob_dir" ;;
        methods) contract_py methods "$source_mode" "$blob_dir" "$(normalize_plugin "${2:-}")" ;;
        args) contract_py args "$source_mode" "$blob_dir" "$(normalize_plugin "${2:-}")" "$(normalize_method "${3:-}")" ;;
        *) exit 0 ;;
    esac
    exit 0
fi

cmd="${1:-help}"
case "$cmd" in
    list)
        contract_py plugins "$source_mode" "$blob_dir"
        exit 0
        ;;
    methods)
        plugin="$(normalize_plugin "${2:-}")"
        [[ -n "$plugin" ]] || die "usage: zcall methods <plugin>"
        contract_py method-summary "$source_mode" "$blob_dir" "$plugin" | column -t -s $'\t'
        exit 0
        ;;
    help)
        plugin="$(normalize_plugin "${2:-}")"
        method="${3:-}"
        if [[ -z "$plugin" ]]; then
            usage
            exit 0
        fi
        if [[ -z "$method" ]]; then
            printf 'Methods for %s:\n' "$plugin"
            contract_py method-summary "$source_mode" "$blob_dir" "$plugin" | column -t -s $'\t'
        else
            contract_py method-json "$source_mode" "$blob_dir" "$plugin" "$(normalize_method "$method")"
        fi
        exit 0
        ;;
    expand)
        shift
        print_only=1
        ;;
esac

[[ $# -ge 2 ]] || die "usage: zcall <plugin> <method> --arguments JSON"
plugin="$(normalize_plugin "$1")"
method="$(normalize_method "$2")"
shift 2

while (($#)); do
    case "$1" in
        -a|--arguments)
            arguments_json="${2:-}"; arguments_was_set=1; shift 2 ;;
        -c|--capability)
            capability_id="${2:-}"; shift 2 ;;
        --actor)
            actor_id="${2:-}"; shift 2 ;;
        --object)
            object_path="${2:-}"; shift 2 ;;
        --interface)
            interface_name="${2:-}"; shift 2 ;;
        --endpoint)
            endpoint="${2:-}"; shift 2 ;;
        --blob-dir)
            blob_dir="${2:-}"; shift 2 ;;
        --source)
            source_mode="${2:-}"; shift 2 ;;
        --print|--dry-run)
            print_only=1; shift ;;
        --*)
            key="${1#--}"
            [[ -n "${2:-}" ]] || die "missing value for --$key"
            method_arg_pairs+=("$key=$2")
            shift 2 ;;
        *)
            die "unknown call option: $1" ;;
    esac
done

if (( ${#method_arg_pairs[@]} > 0 )); then
    if (( arguments_was_set )); then
        die "use either --arguments JSON or method arg flags, not both"
    fi
    arguments_json="$(args_json_from_flags "$plugin" "$method" "${method_arg_pairs[@]}")"
fi

identity="$(contract_py identity "$source_mode" "$blob_dir" "$plugin")"
default_object="$(python3 -c 'import json,sys; print(json.load(sys.stdin)["object_path"])' <<<"$identity")"
default_iface="$(python3 -c 'import json,sys; print(json.load(sys.stdin)["interface_name"])' <<<"$identity")"
object_path="${object_path:-$default_object}"
interface_name="${interface_name:-$default_iface}"

request="$(request_json "$plugin" "$method" "$object_path" "$interface_name")"
mapfile -t headers < <(read_headers)

if ((print_only)); then
    print_expanded "$request" "${headers[@]}"
    printf '%s\n' "$request" | jq . 2>/dev/null || printf '%s\n' "$request"
    exit 0
fi

have grpcurl || die "grpcurl is required for PluginService.CallMethod"
grpcurl -plaintext "${headers[@]}" -d "$request" "$endpoint" "$SERVICE"

//! `PluginObjectBlob` — the sealed, self-describing projection of one
//! `PluginSchema` into one runtime identity (whitepaper "Target Data Model").
//!
//! The blob couples the four identities that must not drift:
//! schema identity (canonical JSON + sha256), D-Bus identity, gRPC identity,
//! and the reflection descriptor identity. It is deliberately redundant at the
//! blob boundary: schema stays authoritative, but the blob is self-describing
//! enough that reflection, GUI, compliance, and dispatch reason about the same
//! object without reassembling identity from scattered files.
//!
//! ## Sealed byte format (zero-copy)
//!
//! ```text
//! offset  size  content
//! 0       8     magic "OPBLOB01"
//! 8       2     format version (u16 LE) = 1
//! 10      2     section count (u16 LE)
//! 12      4     reserved
//! 16      32    sha256 of the SCHEMA_JSON section (the schema hash)
//! 48      16    reserved
//! 64      24*n  section table: tag u32, reserved u32, offset u64, len u64
//! ...           8-byte-aligned section payloads
//! ```
//!
//! Sections: 1 = canonical `PluginSchema` JSON, 2 = `BlobManifest` JSON,
//! 3 = protobuf `FileDescriptorSet`, 4 = compliance/extra metadata JSON.
//!
//! `BlobRef` verifies magic + hash once, then hands out borrowed slices —
//! reads never copy or re-parse the payload. Sealed bytes are fully
//! deterministic for the same schema (sorted maps, no timestamps), so the
//! schema hash doubles as the artifact identity in the filename:
//! `<plugin_id>.<hash16>.blob`.

use crate::descriptor;
use crate::schema::{hex, PluginSchema, SideEffect};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::io;
use std::path::{Path, PathBuf};

pub const MAGIC: &[u8; 8] = b"OPBLOB01";
pub const FORMAT_VERSION: u16 = 1;

pub const SECTION_SCHEMA_JSON: u32 = 1;
pub const SECTION_MANIFEST_JSON: u32 = 2;
pub const SECTION_DESCRIPTOR_SET: u32 = 3;
pub const SECTION_META_JSON: u32 = 4;

const HEADER_LEN: usize = 64;
const SECTION_ENTRY_LEN: usize = 24;

/// D-Bus identity carried by the blob (REQ-7.1/7.2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct DbusIdentity {
    pub bus_name: String,
    pub object_path: String,
    pub interface_name: String,
}

/// gRPC identity: per-method packages/services synthesized from the schema.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct GrpcIdentity {
    /// Fully-qualified service names, sorted.
    pub services: Vec<String>,
    /// Descriptor file names, sorted (parallel to services).
    pub files: Vec<String>,
}

/// Per-method manifest entry copied from `PluginSchema.methods` plus the
/// synthesized gRPC identity — the compliance/audit unit.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MethodManifest {
    pub schema_name: String,
    pub grpc_name: String,
    pub grpc_path: String,
    pub grpc_service: String,
    pub grpc_file: String,
    pub input_message: String,
    pub output_message: String,
    pub subid: String,
    pub required_capability: Option<String>,
    pub side_effect: SideEffect,
    pub idempotent: bool,
    /// Fully-qualified symbols the method's descriptor file defines.
    pub symbols: Vec<String>,
}

/// The blob's self-describing metadata (section 2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BlobManifest {
    /// Runtime blob class. Serialized as `type` so the store can hold active
    /// reflection blobs now and other blob families later without guessing.
    #[serde(rename = "type", default = "default_blob_type")]
    pub blob_type: String,
    pub plugin_id: String,
    pub schema_version: String,
    pub schema_hash: String,
    pub dbus: DbusIdentity,
    pub grpc: GrpcIdentity,
    /// WireGuard-keypair identity of the publishing account (public half
    /// only); its session persists for the life of the account.
    #[serde(default)]
    pub identity: Option<crate::identity::BlobIdentity>,
    pub methods: Vec<MethodManifest>,
}

fn default_blob_type() -> String {
    "active_reflection".to_string()
}

/// Owned, unsealed blob. `seal()` produces the immutable byte image.
#[derive(Debug, Clone)]
pub struct PluginObjectBlob {
    pub manifest: BlobManifest,
    /// Canonical `PluginSchema` JSON (the authoritative contract bytes).
    pub schema_json: String,
    /// Encoded `google.protobuf.FileDescriptorSet` for all plugin methods.
    pub descriptor_set: Vec<u8>,
    /// Compliance / extra metadata (subids, immutable paths, dialect …).
    pub meta_json: String,
}

/// Canonical D-Bus path form: lowercase, hyphens -> underscores.
pub fn canonical_plugin_id(name: &str) -> String {
    name.to_lowercase().replace('-', "_")
}

/// Freeze one `PluginSchema` into a `PluginObjectBlob` (whitepaper "Blob
/// Creation Pipeline" steps 3–9). The schema is the input and stays the
/// authority; nothing here invents contract data.
pub fn blobify(schema: &PluginSchema) -> PluginObjectBlob {
    blobify_with_identity(schema, None)
}

/// `blobify`, stamping the publishing account's WireGuard-keypair identity
/// (public half only) into the manifest.
pub fn blobify_with_identity(
    schema: &PluginSchema,
    identity: Option<crate::identity::BlobIdentity>,
) -> PluginObjectBlob {
    blobify_canonical(schema, schema.canonical_json(), identity)
}

/// `blobify` with the sealed canonical JSON supplied by the caller.
///
/// This is the lossless path for the workspace's authoritative
/// `op_state_store::PluginSchema`: the caller serializes the FULL canonical
/// type (signals, guarantees, category, …) and `schema` is only the reduced
/// working view this crate needs for descriptor synthesis. The sealed
/// SCHEMA_JSON section — and therefore the schema hash — covers the complete
/// contract, never a reduced projection of it.
pub fn blobify_canonical(
    schema: &PluginSchema,
    schema_json: String,
    identity: Option<crate::identity::BlobIdentity>,
) -> PluginObjectBlob {
    let plugin_id = canonical_plugin_id(&schema.name);
    let schema_hash = {
        let mut h = Sha256::new();
        h.update(schema_json.as_bytes());
        hex(&h.finalize())
    };

    let (descriptor_set, method_infos) = descriptor::descriptor_set_for_plugin(&plugin_id, schema);

    let mut methods: Vec<MethodManifest> = method_infos
        .iter()
        .map(|d| {
            let decl = schema
                .methods
                .get(&d.method_name)
                .or_else(|| schema.methods.values().find(|m| m.name == d.method_name))
                .expect("descriptor method must come from PluginSchema.methods");
            MethodManifest {
                schema_name: decl.name.clone(),
                grpc_name: descriptor::pascal_case(&decl.name),
                grpc_path: d.grpc_path.clone(),
                grpc_service: d.service_full.clone(),
                grpc_file: d.file_name.clone(),
                input_message: d.input_full.clone(),
                output_message: d.output_full.clone(),
                subid: decl.subid.clone(),
                required_capability: decl.required_capability.clone(),
                side_effect: decl.side_effect,
                idempotent: decl.idempotent,
                symbols: d.symbols.clone(),
            }
        })
        .collect();
    methods.sort_by(|a, b| a.schema_name.cmp(&b.schema_name));

    let mut services: Vec<String> = methods.iter().map(|m| m.grpc_service.clone()).collect();
    services.sort();
    let mut files: Vec<String> = methods.iter().map(|m| m.grpc_file.clone()).collect();
    files.sort();

    let manifest = BlobManifest {
        blob_type: default_blob_type(),
        plugin_id: plugin_id.clone(),
        schema_version: schema.version.clone(),
        schema_hash,
        dbus: DbusIdentity {
            bus_name: "org.opdbus.v1.plugins".to_string(),
            object_path: format!("/org/opdbus/v1/plugins/{plugin_id}"),
            interface_name: "org.opdbus.v1.Plugin".to_string(),
        },
        grpc: GrpcIdentity { services, files },
        identity,
        methods,
    };

    let meta = serde_json::json!({
        "blob_format": FORMAT_VERSION,
        "dialect": schema.dialect,
        "subids": schema.subids,
        "immutable_paths": schema.immutable_paths,
        "json_schema": schema.to_json_schema(),
    });

    PluginObjectBlob {
        manifest,
        schema_json,
        descriptor_set,
        meta_json: serde_json::to_string(&meta).expect("meta serializes"),
    }
}

impl PluginObjectBlob {
    /// Rehydrate an owned blob from sealed bytes (inverse of `seal`).
    /// `schema_json` is copied verbatim, so `from_sealed(b).seal() == b`
    /// and the schema hash is preserved.
    pub fn from_sealed(bytes: &[u8]) -> Result<Self, String> {
        let r = BlobRef::new(bytes)?;
        Ok(Self {
            manifest: r.manifest()?,
            schema_json: r.schema_json().to_string(),
            descriptor_set: r.descriptor_set().to_vec(),
            meta_json: r.meta_json().unwrap_or("{}").to_string(),
        })
    }

    /// Seal into the immutable byte image. Deterministic: same schema, same bytes.
    pub fn seal(&self) -> Vec<u8> {
        let manifest_json =
            serde_json::to_string(&serde_json::to_value(&self.manifest).unwrap()).unwrap();
        let sections: [(u32, &[u8]); 4] = [
            (SECTION_SCHEMA_JSON, self.schema_json.as_bytes()),
            (SECTION_MANIFEST_JSON, manifest_json.as_bytes()),
            (SECTION_DESCRIPTOR_SET, &self.descriptor_set),
            (SECTION_META_JSON, self.meta_json.as_bytes()),
        ];

        let table_len = sections.len() * SECTION_ENTRY_LEN;
        let mut offset = align8(HEADER_LEN + table_len);
        let mut entries = Vec::with_capacity(sections.len());
        for (tag, bytes) in &sections {
            entries.push((*tag, offset as u64, bytes.len() as u64));
            offset = align8(offset + bytes.len());
        }

        let mut out = Vec::with_capacity(offset);
        out.extend_from_slice(MAGIC);
        out.extend_from_slice(&FORMAT_VERSION.to_le_bytes());
        out.extend_from_slice(&(sections.len() as u16).to_le_bytes());
        out.extend_from_slice(&[0u8; 4]);
        let mut h = Sha256::new();
        h.update(self.schema_json.as_bytes());
        out.extend_from_slice(&h.finalize());
        out.extend_from_slice(&[0u8; 16]);
        debug_assert_eq!(out.len(), HEADER_LEN);

        for (tag, off, len) in &entries {
            out.extend_from_slice(&tag.to_le_bytes());
            out.extend_from_slice(&[0u8; 4]);
            out.extend_from_slice(&off.to_le_bytes());
            out.extend_from_slice(&len.to_le_bytes());
        }

        for ((_, bytes), (_, off, _)) in sections.iter().zip(&entries) {
            while out.len() < *off as usize {
                out.push(0);
            }
            out.extend_from_slice(bytes);
        }
        out
    }

    /// `<plugin_id>.<hash16>.blob` — hash-addressed filename (shm layout).
    pub fn file_name(&self) -> String {
        format!(
            "{}.{}.blob",
            self.manifest.plugin_id,
            &self.manifest.schema_hash[..16]
        )
    }

    /// Atomic write: seal to `<name>.blob.tmp`, then rename over the final
    /// path. Readers scanning the directory never observe a partial blob
    /// (`.tmp` fails the `.blob` extension filter; rename(2) is atomic on
    /// the same filesystem).
    pub fn write_to_dir(&self, dir: &Path) -> io::Result<PathBuf> {
        std::fs::create_dir_all(dir)?;
        let path = dir.join(self.file_name());
        let tmp = dir.join(format!("{}.tmp", self.file_name()));
        std::fs::write(&tmp, self.seal())?;
        std::fs::rename(&tmp, &path)?;
        Ok(path)
    }
}

fn align8(n: usize) -> usize {
    (n + 7) & !7
}

/// Zero-copy view over sealed blob bytes. Construction verifies magic,
/// bounds, and the schema hash once; accessors return borrowed slices.
pub struct BlobRef<'a> {
    bytes: &'a [u8],
    sections: Vec<(u32, usize, usize)>,
}

impl<'a> BlobRef<'a> {
    pub fn new(bytes: &'a [u8]) -> Result<Self, String> {
        if bytes.len() < HEADER_LEN || &bytes[..8] != MAGIC {
            return Err("not an OPBLOB01 blob".into());
        }
        let version = u16::from_le_bytes([bytes[8], bytes[9]]);
        if version != FORMAT_VERSION {
            return Err(format!("unsupported blob format version {version}"));
        }
        let count = u16::from_le_bytes([bytes[10], bytes[11]]) as usize;
        let table_end = HEADER_LEN + count * SECTION_ENTRY_LEN;
        if bytes.len() < table_end {
            return Err("section table overruns blob".into());
        }
        let mut sections = Vec::with_capacity(count);
        for i in 0..count {
            let e = HEADER_LEN + i * SECTION_ENTRY_LEN;
            let tag = u32::from_le_bytes(bytes[e..e + 4].try_into().unwrap());
            let off = u64::from_le_bytes(bytes[e + 8..e + 16].try_into().unwrap()) as usize;
            let len = u64::from_le_bytes(bytes[e + 16..e + 24].try_into().unwrap()) as usize;
            if off + len > bytes.len() {
                return Err(format!("section {tag} overruns blob"));
            }
            sections.push((tag, off, len));
        }
        let blob = Self { bytes, sections };

        // Verify schema hash (blob-drift guard).
        let schema = blob
            .section(SECTION_SCHEMA_JSON)
            .ok_or("missing schema section")?;
        let mut h = Sha256::new();
        h.update(schema);
        if h.finalize().as_slice() != &bytes[16..48] {
            return Err("schema hash mismatch: blob is corrupt or tampered".into());
        }
        Ok(blob)
    }

    fn section(&self, tag: u32) -> Option<&'a [u8]> {
        self.sections
            .iter()
            .find(|(t, _, _)| *t == tag)
            .map(|(_, off, len)| &self.bytes[*off..*off + *len])
    }

    /// Canonical `PluginSchema` JSON — borrowed, zero-copy.
    pub fn schema_json(&self) -> &'a str {
        std::str::from_utf8(self.section(SECTION_SCHEMA_JSON).unwrap())
            .expect("schema section is UTF-8")
    }

    pub fn manifest_json(&self) -> &'a str {
        std::str::from_utf8(self.section(SECTION_MANIFEST_JSON).unwrap())
            .expect("manifest section is UTF-8")
    }

    /// Encoded `FileDescriptorSet` — borrowed, zero-copy; slices of this can
    /// be served directly to reflection clients.
    pub fn descriptor_set(&self) -> &'a [u8] {
        self.section(SECTION_DESCRIPTOR_SET).unwrap_or(&[])
    }

    pub fn meta_json(&self) -> Option<&'a str> {
        self.section(SECTION_META_JSON)
            .and_then(|b| std::str::from_utf8(b).ok())
    }

    pub fn schema_hash_hex(&self) -> String {
        hex(&self.bytes[16..48])
    }

    /// Parse the manifest (the one intentional allocation on the read path;
    /// everything else stays borrowed).
    pub fn manifest(&self) -> Result<BlobManifest, String> {
        serde_json::from_str(self.manifest_json()).map_err(|e| format!("manifest parse: {e}"))
    }

    /// Reconstruct the authoritative `PluginSchema` from the sealed bytes.
    ///
    /// This is the reduced working view; blobs sealed via
    /// `blobify_plugin_schema` carry the full workspace schema — use
    /// [`Self::state_store_schema`] to read it without loss.
    pub fn plugin_schema(&self) -> Result<PluginSchema, String> {
        serde_json::from_str(self.schema_json()).map_err(|e| format!("schema parse: {e}"))
    }

    /// Reconstruct the FULL canonical `op_state_store::PluginSchema`
    /// (signals, guarantees, category, …) from the sealed bytes. The plugin
    /// IS this schema; consumers must read it from here, never from a
    /// registry or a monolith file.
    pub fn state_store_schema(&self) -> Result<op_state_store::PluginSchema, String> {
        serde_json::from_str(self.schema_json()).map_err(|e| format!("schema parse: {e}"))
    }
}

